import React, { useState, useEffect } from 'react';
import AddCameraModal from './AddCameraModal';

export default function TopBar() {
  const [time,      setTime]      = useState('');
  const [showModal, setShowModal] = useState(false);

  useEffect(() => {
    const tick = () => {
      const n = new Date();
      let h = n.getHours(), m = n.getMinutes(), s = n.getSeconds();
      const ap = h >= 12 ? 'PM' : 'AM';
      h = h % 12 || 12;
      const p = v => v.toString().padStart(2, '0');
      setTime(`May 30, 2026  |  ${p(h)}:${p(m)}:${p(s)} ${ap}`);
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);

  return (
    <>
      <div style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        padding: '10px 16px', borderBottom: '1px solid #1e2d47',
        background: '#111827', flexShrink: 0
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <span style={{ fontSize: 20, color: '#3b82f6' }}>🛡</span>
          <span style={{ fontSize: 14, fontWeight: 700, color: '#3b82f6', letterSpacing: '.5px' }}>
            BRAWL DETECTION SYSTEM
          </span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
          <span style={{ fontSize: 11, color: '#94a3b8' }}>{time}</span>
          <span style={{ fontSize: 18, cursor: 'pointer' }}>🔔</span>
          <span style={{ fontSize: 12, color: '#94a3b8', cursor: 'pointer' }}>👤 Admin ▾</span>
          <button
            onClick={() => setShowModal(true)}
            style={{
              background: '#3b82f6', color: '#fff', border: 'none',
              padding: '6px 14px', borderRadius: 6, fontSize: 11,
              fontWeight: 600, cursor: 'pointer'
            }}
          >
            + Add Camera
          </button>
        </div>
      </div>

      {showModal && <AddCameraModal onClose={() => setShowModal(false)} />}
    </>
  );
}
